const ee = require('@google/earthengine');
const privateKey = require('../auth_keys/test-project-473922-29f05d49bed7');

async function runAnalysis() {
  try {
    // 1. Geometry & Time Definitions
    const states = ee.FeatureCollection('TIGER/2018/States');
    const caGeom = states.filter(ee.Filter.eq('NAME', 'California')).geometry();
    const msGeom = states.filter(ee.Filter.eq('NAME', 'Mississippi')).geometry();
    const start = ee.Date('2005-07-12');
    const end = ee.Date('2005-07-20'); // end-exclusive, covers 12-19

    // 2. Data Acquisition & Check with fallbacks
    function getCol(id) {
      return ee.ImageCollection(id).filterDate(start, end).select(['LST_Day_1km', 'QC_Day']);
    }
    let source = 'MODIS/061/MOD11A1';
    let col = getCol(source);
    let size = await col.size().getInfo();
    if (size === 0) {
      source = 'MODIS/006/MOD11A1';
      col = getCol(source);
      size = await col.size().getInfo();
    }
    if (size === 0) {
      source = 'MODIS/061/MYD11A1'; // Aqua fallback
      col = getCol(source);
      size = await col.size().getInfo();
    }
    if (size === 0) {
      console.log(`Collection: none found for ${start.format('YYYY-MM-dd').getInfo()} to ${end.format('YYYY-MM-dd').getInfo()}`);
      console.log('C1');
      return;
    }

    // 3. Masking strategy: MODIS LST good quality only (QC bits 0-1 == 00), and valid LST > 0
    function maskModisLST(img) {
      const lst = img.select('LST_Day_1km');
      const qc = img.select('QC_Day');
      const good = qc.bitwiseAnd(3).eq(0); // bits 0-1 == 00
      const valid = lst.gt(0);
      const m = good.and(valid);
      const lstC = lst.updateMask(m).multiply(0.02).subtract(273.15); // K->C
      return lstC.rename('LST').copyProperties(img, img.propertyNames());
    }
    const colMasked = col.map(maskModisLST);
    const meanImg = colMasked.mean().rename('LST');

    // Helper to compute stats per region
    async function regionStats(region) {
      const scale = 1000;
      const reducers = ee.Reducer.mean().combine({reducer2: ee.Reducer.count(), sharedInputs: true});
      const stats = await meanImg.reduceRegion({
        reducer: reducers,
        geometry: region,
        scale: scale,
        maxPixels: 1e9,
        bestEffort: true
      }).getInfo();
      const validCount = stats ? (stats['LST_count'] || 0) : 0;
      const meanVal = stats ? stats['LST_mean'] : null;

      // total potential pixels at this scale (unmasked)
      const totalCount = await ee.Image(1).reduceRegion({
        reducer: ee.Reducer.count(),
        geometry: region,
        scale: scale,
        maxPixels: 1e9,
        bestEffort: true
      }).get('constant').getInfo();

      return {validCount, totalCount, meanVal};
    }

    const [ca, ms] = await Promise.all([regionStats(caGeom), regionStats(msGeom)]);

    console.log(`Collection: ${source}, Images: ${size}`);
    const pct = (v, t) => (t && t > 0 ? (100 * v / t) : 0);
    console.log(`CA valid px: ${ca.validCount} / ${ca.totalCount} (${pct(ca.validCount, ca.totalCount).toFixed(1)}%)`);
    console.log(`MS valid px: ${ms.validCount} / ${ms.totalCount} (${pct(ms.validCount, ms.totalCount).toFixed(1)}%)`);

    // 4. Validation for C2 and C3
    if ((ca.totalCount || 0) === 0 || (ms.totalCount || 0) === 0) {
      console.log('C3'); // No total pixels indicates an unexpected failure in geometry/scale
      return;
    }
    if (ca.validCount === 0 || ms.validCount === 0) {
      console.log('C2');
      return;
    }
    const caMean = ca.meanVal;
    const msMean = ms.meanVal;
    const validNums = Number.isFinite(caMean) && Number.isFinite(msMean);
    const plausible = validNums &&
                      (caMean > -50 && caMean < 80) &&
                      (msMean > -50 && msMean < 80);
    if (!plausible) {
      console.log('C3');
      return;
    }

    console.log(`CA mean LST (°C): ${caMean.toFixed(2)}`);
    console.log(`MS mean LST (°C): ${msMean.toFixed(2)}`);
    console.log(`Diff CA-MS (°C): ${(caMean - msMean).toFixed(2)}`);

    // 5. Final Answer
    // Question: Was CA higher than MS?
    if (caMean > msMean) {
      console.log('A');
    } else {
      console.log('B');
    }
  } catch (err) {
    console.log(`Error: ${err.message || err}`);
    console.log('D');
  }
}

async function initEE() {
  await new Promise((resolve, reject) => {
    ee.data.authenticateViaPrivateKey(privateKey, resolve, reject);
  });
  await new Promise((resolve, reject) => {
    ee.initialize(null, null, resolve, reject);
  });
  await runAnalysis();
}

initEE();
